INSERT OR IGNORE INTO terms(code,name,version,scope,body,status) VALUES('PRIVACY/NHN','Thông báo Quyền riêng tư Nhà Hán Ngữ','29/08/2026','Toàn hệ thống','# THÔNG BÁO QUYỀN RIÊNG TƯ NHÀ HÁN NGỮ\nNhà Hán Ngữ thu thập dữ liệu cần thiết để tiếp nhận đăng ký hoạt động, quản lý hồ sơ, hỗ trợ, cấp và xác thực Giấy chứng nhận. Quyền truy cập được giới hạn theo vai trò và mục đích nghiệp vụ.','published');
